/**
 * Cursor-managed durable KV for hosted **architecture v2** agents.
 *
 * Reads return opaque version tokens. Writes support unconditional updates,
 * create-if-absent, and compare-and-swap. Lists use stable key pagination,
 * and this client drains every page before returning.
 *
 * This backend is selected automatically for architecture v2. Authors do
 * not import it, and `agent/storage.ts` is rejected on v2.
 */
import { CURSOR_HOSTED_STORAGE, cursorHostedStorage, storageRpc, } from "./cursor-hosted.js";
const KV_V2_PREFIX = "/internal/agentsdk/kv";
function toCasResult(response) {
    if (response.ok) {
        if (response.version === null) {
            throw new Error("cursorHostedStorageV2: conditional write succeeded without a version token");
        }
        return { ok: true, version: response.version };
    }
    const current = response.current === null
        ? undefined
        : {
            value: response.current.value ?? null,
            version: response.current.version,
        };
    return { ok: false, current };
}
/**
 * Drain every page of a v2 `list` scan. The server pages by keyset (each
 * `nextCursor` is the strictly-greatest key returned so far), so a cursor
 * that fails to advance means a broken server — fail loudly rather than
 * loop forever.
 */
async function listAllPages(options, body) {
    const entries = [];
    let cursor;
    for (;;) {
        const page = await storageRpc(options, `${KV_V2_PREFIX}/list`, cursor === undefined ? body : { ...body, cursor });
        entries.push(...page.entries);
        if (page.nextCursor === null) {
            return entries;
        }
        if (cursor !== undefined && page.nextCursor <= cursor) {
            throw new Error(`cursorHostedStorageV2: list("${body.prefix}") cursor did not advance`);
        }
        cursor = page.nextCursor;
    }
}
/**
 * Architecture-v2 managed storage methods. The platform spreads these into
 * `defineStorage({...})`. Session history uses the framework file store, so
 * this backend does not need write-time ordering.
 */
export function cursorHostedStorageV2(options = {}) {
    // Eval runs use the managed eval-storage path.
    const v1 = cursorHostedStorage(options);
    return {
        [CURSOR_HOSTED_STORAGE]: true,
        async put(key, value) {
            await storageRpc(options, `${KV_V2_PREFIX}/put`, { key, value });
        },
        async get(key) {
            const result = await storageRpc(options, `${KV_V2_PREFIX}/get`, { key });
            if (!result.found) {
                return undefined;
            }
            return result.value ?? undefined;
        },
        async delete(key) {
            await storageRpc(options, `${KV_V2_PREFIX}/delete`, { key });
        },
        async list(prefix) {
            const entries = await listAllPages(options, { prefix });
            return entries.map((entry) => ({
                key: entry.key,
                value: entry.value ?? null,
            }));
        },
        cas: {
            async getWithVersion(key) {
                const result = await storageRpc(options, `${KV_V2_PREFIX}/get`, { key });
                if (!result.found || result.version === null) {
                    return undefined;
                }
                return { value: result.value ?? null, version: result.version };
            },
            async putIfAbsent(key, value) {
                const result = await storageRpc(options, `${KV_V2_PREFIX}/put`, {
                    key,
                    value,
                    ifAbsent: true,
                });
                return toCasResult(result);
            },
            async putIfVersion(key, value, expectedVersion) {
                const result = await storageRpc(options, `${KV_V2_PREFIX}/put`, {
                    key,
                    value,
                    ifVersion: expectedVersion,
                });
                return toCasResult(result);
            },
            async listKeys(prefix) {
                const entries = await listAllPages(options, {
                    prefix,
                    keysOnly: true,
                });
                return entries.map((entry) => entry.key);
            },
        },
        evals: v1.evals,
    };
}
